import{_ as t,c as a,o,ae as l}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"Select Field","description":"Select Field","frontmatter":{"title":"Select Field","description":"Select Field"},"headers":[],"relativePath":"guide/field-types/select-field.md","filePath":"guide/field-types/select-field.md"}'),i={name:"guide/field-types/select-field.md"};function n(d,e,s,r,c,u){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="select-field" tabindex="-1">Select Field <a class="header-anchor" href="#select-field" aria-label="Permalink to &quot;Select Field&quot;">​</a></h1><p>The Select Field data type is for columns with multiple options in a dropdown list. It&#39;s one of the most useful features in Ninja Tables. You can decide the Select Field data type right from the start when you add a column to the table. From your dashboard, go to the Ninja Tables plugin → Tables (the table where you want to add Column) → Add Column.</p><h2 id="select-field-data-type-in-ninja-tables" tabindex="-1">Select Field Data Type in Ninja Tables <a class="header-anchor" href="#select-field-data-type-in-ninja-tables" aria-label="Permalink to &quot;Select Field Data Type in Ninja Tables&quot;">​</a></h2><p>This data type is used to add multiple options in a dropdown format when certain data is entered. It&#39;s helpful if the column needs different data for each row. For example, &quot;Yes&quot; for one and &quot;No&quot; for another. No need to type every time if you can just select it from a dropdown.</p><ul><li>Go to the <strong>Data Type</strong> option and select the **Select Field **type of the column and add a column. <img src="https://ninjatables.com/wp-content/uploads/2023/09/Select-field-in-data-type-1024x686.png" alt="Select field in data type"></li></ul><h3 id="select-items" tabindex="-1"><strong>Select Items</strong> <a class="header-anchor" href="#select-items" aria-label="Permalink to &quot;**Select Items**&quot;">​</a></h3><p>After choosing this Select field,** <strong>the</strong> Select Items **field will automatically appear. This is where you add the elements of the dropdown list in the specific column. Here we&#39;ve added &quot;Yes&quot; and &quot;No&quot; for the dropdown.</p><h3 id="placeholder" tabindex="-1"><strong>Placeholder</strong> <a class="header-anchor" href="#placeholder" aria-label="Permalink to &quot;**Placeholder**&quot;">​</a></h3><p>In this option, you can enter a custom placeholder text. For example, we&#39;ve added, &quot;Profitable?&quot; and we&#39;ll pick yes/no from the dropdown.</p><h3 id="enable-multi-selection" tabindex="-1"><strong>Enable Multi-Selection</strong> <a class="header-anchor" href="#enable-multi-selection" aria-label="Permalink to &quot;**Enable Multi-Selection**&quot;">​</a></h3><p>There’s an additional feature called Enable Multi-Selection. This allows you to choose multiple elements to be added in a single column. We can choose both &quot;Yes&quot; and &quot;No&quot; if we enable it. Select Items, Placeholder, and Enable Multi-selection fields are pro features! Here&#39;s how the table looks with Select Field. <img src="https://ninjatables.com/wp-content/uploads/2023/09/select-field-dropdown-1024x444.png" alt="select field dropdown"> Use this feature to show if the product is in stock or not if you have a product table. Or, you can use it to display icons. Let us know your thoughts.</p>',11)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
